//! Whole actor-handler semantics on the SAME original source/header/BODY owners.
//! No parser, copied semantic graph, proc cache or alternative statement walk.
use crate::{reactive_original_source::ReadSource,reactive_global_source::{Source,Body,SelectedCallable},reactive_reads_native::Failure,key_policy_control::{self as kc,Control},captured_allow_annotations::Operation,silicon_actor_policy::{self as judge,ActorTest,Taint,ActorExpression}};
use dm_syntax::{Expr,ExprKind,Statement,StatementKind,Span,VisitDecision};
use std::{io,collections::{BTreeMap,BTreeSet,HashSet}};
pub(crate) type MacroLines=BTreeSet<(String,u32)>;
fn oom(s:&ReadSource<'_>)->Failure{s.budget().deny();Failure::Operational(io::ErrorKind::OutOfMemory.into())}
fn charge(s:&ReadSource<'_>,bytes:Option<usize>)->Result<(),Failure>{s.checkpoint()?;s.budget().charge(bytes.ok_or_else(||oom(s))?).map_err(|m|Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,m)))}
fn own(s:&ReadSource<'_>,text:&str)->Result<String,Failure>{kc::own(&mut Operation{budget:s.budget(),poll:&||s.checkpoint()},text)}
fn room<T>(s:&ReadSource<'_>,rows:&mut Vec<T>)->Result<(),Failure>{kc::row(&mut Operation{budget:s.budget(),poll:&||s.checkpoint()},rows)}
fn header_error(e:dm_tree::frontend::BodySyntaxFailure)->Failure{match e{dm_tree::frontend::BodySyntaxFailure::Operational(e)=>Failure::Operational(e),dm_tree::frontend::BodySyntaxFailure::Syntax(e)=>Failure::Unsupported(e.message)}}
fn headers<'a>(s:&'a ReadSource<'_>,ordinal:usize)->Result<dm_tree::frontend::SourceParameterView<'a>,Failure>{let view=s.inputs().archive().header_parameters_using(ordinal,&||s.checkpoint()).map_err(header_error)?;let occurrence=s.inputs().archive().occurrences().get(ordinal).ok_or("silicon header occurrence absent")?;view.require_for(s.tree(),occurrence)?;Ok(view)}
fn is_handler(s:&ReadSource<'_>,ordinal:usize,owner:&str,name:&str)->Result<bool,Failure>{
 let view=headers(s,ordinal)?;let mut rows=view.entries()?.iter();let mut failure=None;
 let kinds=std::iter::from_fn(||{if failure.is_some(){return None}let parameter=rows.next()?;let result=(||{s.checkpoint()?;Ok::<_,Failure>(if !parameter.array_brackets().is_empty(){judge::HandlerParameter::Other}else{judge::handler_parameter(view.type_component(parameter,0)?,view.type_component(parameter,1)?,view.type_component(parameter,2)?)})})();match result{Ok(kind)=>Some(kind),Err(error)=>{failure=Some(error);None}}});
 let actual=judge::is_handler_kinds(owner,name,kinds);if let Some(error)=failure{return Err(error)}Ok(actual)
}
struct Parameter{name:String,path:Option<String>}
fn parameters(s:&ReadSource<'_>,ordinal:usize)->Result<Vec<Parameter>,Failure>{let view=headers(s,ordinal)?;let span=view.header_span()?;charge(s,span.end.checked_sub(span.start).and_then(|n|n.checked_mul(16)).and_then(|n|n.checked_add(2048)))?;let mut out=Vec::new();for p in view.entries()?{s.checkpoint()?;room(s,&mut out)?;out.push(Parameter{name:own(s,view.name(p)?)?,path:view.type_path(p)?});}Ok(out)}
fn bare(mut e:&Expr)->Option<&str>{while let ExprKind::Group(inner)=&e.kind{e=inner;}e.bare_name()}
fn types(s:&ReadSource<'_>,body:&dyn Body,params:&[Parameter])->Result<BTreeMap<String,String>,Failure>{let mut map=BTreeMap::new();for p in params{if let Some(path)=p.path.as_ref().filter(|p|!p.is_empty()){charge(s,p.name.len().checked_add(path.len()).and_then(|n|n.checked_mul(4)).and_then(|n|n.checked_add(1024)))?;map.insert(own(s,&p.name)?,own(s,path)?);}}let locals=body.source_locals()?;charge(s,Some(locals.scope_admission()?))?;for local in locals.entries()?{s.checkpoint()?;if !matches!(local.source_kind,dm_syntax::LocalSourceKind::Statement|dm_syntax::LocalSourceKind::CommaContinuation){continue}if let Some(path)=locals.type_path(local)?.filter(|path|!path.is_empty()){let name=locals.name(local)?;charge(s,name.len().checked_add(path.len()).and_then(|n|n.checked_mul(4)).and_then(|n|n.checked_add(1024)))?;map.insert(own(s,name)?,path);}}Ok(map)}
#[derive(Eq,PartialEq,Hash)]struct Edge{owner:String,name:String,actors:Vec<usize>,acts:Vec<usize>}
fn positions(s:&ReadSource<'_>,taint:&Taint,args:&[Expr],actor:bool)->Result<Vec<usize>,Failure>{let mut out=Vec::new();let mut i=0usize;for arg in args{s.checkpoint()?;if !dm_analysis::original_base_terms::retains_call_argument(arg){continue}if if actor{taint.is_actor(arg)}else{taint.is_act(arg)}{room(s,&mut out)?;out.push(i);}i=i.checked_add(1).ok_or_else(||oom(s))?;}Ok(out)}
fn resolve<'a>(s:&'a ReadSource<'_>,owner:&str,name:&str,global:bool,fallback:bool)->Result<Option<crate::reactive_global_source::Callable<'a>>,Failure>{
 let selected=Source::callable(s,if global{"/"}else{owner},name)?;
 match selected{SelectedCallable::Source(p)=>Ok(Some(p)),SelectedCallable::Builtin=>Ok(None),SelectedCallable::Missing if !global&&fallback=>match Source::callable(s,"/",name)?{SelectedCallable::Source(p)=>Ok(Some(p)),_=>Ok(None)},SelectedCallable::Missing=>Ok(None)}
}
fn edge(s:&ReadSource<'_>,owner:&str,name:&str,args:&[Expr],global:bool,fallback:bool,taint:&Taint,pending:&mut Vec<Edge>)->Result<(),Failure>{let Some(p)=resolve(s,owner,name,global,fallback)?else{return Ok(())};let actors=positions(s,taint,args,true)?;let acts=positions(s,taint,args,false)?;if actors.is_empty()&&acts.is_empty(){return Ok(())}room(s,pending)?;pending.push(Edge{owner:own(s,p.owner)?,name:own(s,p.name)?,actors,acts});Ok(())}
fn first_follow_is_call(s:&ReadSource<'_>,mut e:&Expr)->Result<bool,Failure>{let mut first=false;loop{s.checkpoint()?;match &e.kind{ExprKind::Call{callee,..}if matches!(callee.kind,ExprKind::Member{..}|ExprKind::SafeMember{..})=>{first=true;let object=match &callee.kind{ExprKind::Member{object,..}|ExprKind::SafeMember{object,..}=>object.as_ref(),_=>unreachable!()};e=object;},_=>match dm_analysis::original_base_terms::base_child(e){Some(child)=>{first=false;e=child},None=>return Ok(first)}}}}
fn calls(s:&ReadSource<'_>,owner:&str,types:&BTreeMap<String,String>,e:&Expr,taint:&Taint,pending:&mut Vec<Edge>)->Result<(),Failure>{
 let leaf=dm_analysis::original_base_terms::leaf_using(e,&mut||s.checkpoint())?;
 if let ExprKind::Call{callee,args}=&leaf.kind{match &callee.kind{ExprKind::Ident(name)if dm_analysis::original_base_terms::ordinary_call_name(name)&&!first_follow_is_call(s,e)?=>edge(s,owner,name,args,false,true,taint,pending)?,ExprKind::Unary{op,value}if op=="::"=>{if let ExprKind::Ident(name)=&value.kind{edge(s,"/",name,args,true,false,taint,pending)?}},_=>()}}
 // Exactly one Follow::Call with bare original Ident receiver; chains do not qualify.
 if let ExprKind::Call{callee,args}=&e.kind{if let ExprKind::Member{object,selector,..}|ExprKind::SafeMember{object,selector,..}=&callee.kind{if let ExprKind::Ident(receiver)=&object.kind{if receiver=="src"{edge(s,owner,selector,args,false,false,taint,pending)?}else if let Some(ty)=types.get(receiver){edge(s,ty,selector,args,false,false,taint,pending)?;}}}}
 Ok(())
}
fn prefab_path(s:&ReadSource<'_>,mut e:&Expr)->Result<Option<String>,Failure>{while let ExprKind::Group(inner)=&e.kind{e=inner;}if let ExprKind::ObjectInitializer{object,..}=&e.kind{e=object;}let ExprKind::TypePath(path)=&e.kind else{return Ok(None)};if !path.starts_with(['/','.',':']){return Err("silicon prefab lacks actual native path components".into())}charge(s,path.len().checked_mul(4).and_then(|n|n.checked_add(128)))?;let mut out=String::new();for part in path.split(['/', '.', ':']).filter(|s|!s.is_empty()){s.checkpoint()?;out.push('/');out.push_str(part);}Ok(Some(out))}
struct Pass<'a,'b>{source:&'a ReadSource<'a>,body:&'b dyn Body,ordinal:usize,handler:&'b str,owner:&'b str,rel:&'b str,depth:usize,taint:&'b mut Taint,types:&'b BTreeMap<String,String>,assignments:bool,found:Vec<ActorTest>,pending:Vec<Edge>,macro_lines:BTreeSet<u32>,error:Option<Failure>}
impl Pass<'_,'_>{
 fn statement_using(&mut self,node:&Statement)->Result<(),Failure>{self.source.checkpoint()?;if !self.assignments{return Ok(())}let mut c=Operation{budget:self.source.budget(),poll:&||self.source.checkpoint()};match &node.kind{StatementKind::Var{value:Some(value),..}=>{let locals=self.body.source_locals()?;let rows=locals.in_current_span(node.header_span)?;if rows.len()!=1{return Err("silicon grouped-local initializer has no exact variable root owner".into())}self.taint.take_using(locals.name(&rows[0])?,value,&mut c)?;},StatementKind::Assign{target,op,value}if op=="="=>{if let Some(name)=bare(target){self.taint.take_using(name,value,&mut c)?;}},_=>()}Ok(())}
 fn expression_using(&mut self,node:&Expr,chain:bool,at:Span)->Result<(),Failure>{self.source.checkpoint()?;if chain||self.assignments{return Ok(())}let(_,line)=self.source.site(self.ordinal,at.start)?;
  if let ExprKind::Call{callee,args}=&node.kind{let mut old_args=args.iter().filter(|arg|dm_analysis::original_base_terms::retains_call_argument(arg));let first=old_args.next();let second=old_args.next();let extra=old_args.next().is_some();if matches!(&callee.kind,ExprKind::Ident(name)if name=="istype")&&!extra&&first.is_some_and(|arg|self.taint.is_actor(arg)){if let Some(path)=match second{Some(path)=>prefab_path(self.source,path)?.filter(|path|judge::silicon_type(path)),None=>None}{room(self.source,&mut self.found)?;self.found.push(ActorTest{rule:if self.depth==0{"handler_actor_istype"}else{"helper_actor_check"},rel:own(self.source,self.rel)?,line,handler:own(self.source,self.handler)?,tested:path});}}}
  if self.depth==0{charge(self.source,Some(1024))?;self.macro_lines.insert(line);}if self.depth<judge::MAX_DEPTH{calls(self.source,self.owner,self.types,node,self.taint,&mut self.pending)?;}Ok(())
 }
 fn stop(&mut self,result:Result<(),Failure>)->VisitDecision{match result{Ok(())=>VisitDecision::Descend,Err(e)=>{if self.error.is_none(){self.error=Some(e)}VisitDecision::Stop}}}
}
impl dm_analysis::policy_body_observation::BaseChainVisitor for Pass<'_,'_>{
 fn statement(&mut self,node:&Statement)->VisitDecision{if self.error.is_some(){return VisitDecision::Stop}let result=self.statement_using(node);self.stop(result)}
 fn expression(&mut self,node:&Expr,chain:bool)->VisitDecision{let result=self.expression_using(node,chain,node.span);self.stop(result)}
 fn projected_expression(&mut self,node:dm_syntax::ProjectedExprView<'_>,chain:bool)->VisitDecision{let result=self.expression_using(node.original(),chain,node.current_span());self.stop(result)}
 fn expression_at(&mut self,node:&Expr,chain:bool,at:Span)->VisitDecision{let result=self.expression_using(node,chain,at);self.stop(result)}
 fn projected_expression_at(&mut self,node:dm_syntax::ProjectedExprView<'_>,chain:bool,at:Span)->VisitDecision{let result=self.expression_using(node.original(),chain,at);self.stop(result)}
 fn if_condition_span(&mut self,condition:&Expr,_at:Span)->Result<Span,&'static str>{match self.body.statement_body().parsed().control_origin(condition.span){Some(opening)=>Ok(opening),None=>{if self.error.is_none(){self.error=Some(Failure::from("silicon If condition lacks actual original opening cursor"));}Err("silicon If condition lacks actual original opening cursor")}}}
 fn frame_capacity(&mut self,n:usize)->Result<(),&'static str>{match charge(self.source,Some(n)){Ok(())=>Ok(()),Err(e)=>{if self.error.is_none(){self.error=Some(e)}Err("silicon actor walk admission refused")}}}
 fn frame_overflow(&mut self)->&'static str{if self.error.is_none(){self.error=Some(oom(self.source));}"silicon actor frame overflow"}
 fn frame_allocation_failed(&mut self)->&'static str{self.frame_overflow()}
}
struct Walker<'a>{source:&'a ReadSource<'a>,macros:&'a MacroLines,found:Vec<ActorTest>,visited:HashSet<Edge>}
impl Walker<'_>{
 fn body(&mut self,handler:&str,ordinal:usize,owner:&str,params:Vec<Parameter>,taint:Taint,depth:usize)->Result<(),Failure>{let source=self.source;let rel=Source::relative_body_file(source,ordinal)?;let mut returned=None;let mut initial=Some(taint);Source::with_body(source,ordinal,&mut|body|{
  let types=types(source,body,&params)?;let mut taint=initial.take().ok_or("silicon actual body callback repeated")?;
  loop{source.checkpoint()?;let before=(taint.acts.len(),taint.actors.len());let mut pass=Pass{source,body,ordinal,handler,owner,rel:&rel,depth,taint:&mut taint,types:&types,assignments:true,found:Vec::new(),pending:Vec::new(),macro_lines:BTreeSet::new(),error:None};let coverage=dm_analysis::policy_body_observation::observe_base_chains(body.statement_body().view(),&mut pass);if let Some(e)=pass.error{return Err(e)}coverage.map_err(Failure::from)?;if (taint.acts.len(),taint.actors.len())==before{break}}
  let mut pass=Pass{source,body,ordinal,handler,owner,rel:&rel,depth,taint:&mut taint,types:&types,assignments:false,found:Vec::new(),pending:Vec::new(),macro_lines:BTreeSet::new(),error:None};let coverage=dm_analysis::policy_body_observation::observe_base_chains(body.statement_body().view(),&mut pass);if let Some(e)=pass.error{return Err(e)}coverage.map_err(Failure::from)?;
  for line in pass.macro_lines{source.checkpoint()?;charge(source,rel.len().checked_mul(4).and_then(|n|n.checked_add(128)))?;if self.macros.contains(&(rel.clone(),line)){pass.found.retain(|row|row.line!=line);room(source,&mut pass.found)?;pass.found.push(ActorTest{rule:"handler_actor_check",rel:own(source,&rel)?,line,handler:own(source,handler)?,tested:own(source,"macro")?});}}
  for row in pass.found{room(source,&mut self.found)?;self.found.push(row);}returned=Some(pass.pending);Ok(())})?;
  for edge in returned.ok_or("silicon body callback omitted")?{source.checkpoint()?;if self.visited.contains(&edge){continue}let owner=own(source,&edge.owner)?;let name=own(source,&edge.name)?;charge(source,edge.actors.len().checked_add(edge.acts.len()).and_then(|n|n.checked_mul(std::mem::size_of::<usize>()*4)).and_then(|n|n.checked_add(1024)))?;let actors=edge.actors.clone();let acts=edge.acts.clone();kc::set_room(&mut Operation{budget:source.budget(),poll:&||source.checkpoint()},&mut self.visited)?;self.visited.insert(edge);let SelectedCallable::Source(proc)=Source::callable(source,&owner,&name)?else{continue};if is_handler(source,proc.ordinal,proc.owner,proc.name)?{continue}let params=parameters(source,proc.ordinal)?;let mut next=Taint::default();for i in actors{if let Some(p)=params.get(i){charge(source,p.name.len().checked_mul(4).and_then(|n|n.checked_add(1024)))?;next.actors.insert(own(source,&p.name)?);}}for i in acts{if let Some(p)=params.get(i){charge(source,p.name.len().checked_mul(4).and_then(|n|n.checked_add(1024)))?;next.acts.insert(own(source,&p.name)?);}}self.body(handler,proc.ordinal,proc.owner,params,next,depth+1)?;
  }Ok(())
 }
}
struct GroupWork<'a>{source:&'a ReadSource<'a>,peak:usize}
impl dm_analysis::policy_body_demand::WorkspaceWork for GroupWork<'_>{type Error=Failure;const CHECKED:bool=true;fn checkpoint(&mut self)->Result<(),Failure>{self.source.checkpoint()?;self.source.require()?;Ok(())}fn retain(&mut self,n:usize)->Result<(),Failure>{charge(self.source,Some(n))}fn temporary(&mut self,n:usize)->Result<(),Failure>{if n>self.peak{charge(self.source,Some(n-self.peak))?;self.peak=n;}Ok(())}fn overflow(&mut self)->Failure{oom(self.source)}fn allocation_failed(&mut self)->Failure{oom(self.source)}fn body<'a>(&mut self,_:&'a dm_tree::frontend::BodyArchive,_:usize)->Result<dm_tree::frontend::ArchivedBody<'a>,Failure>{Err("silicon header discovery cannot request a body".into())}}
/// Complete actor discovery and helper semantics; raw rules/report admission are
/// separate caller-owned phases. No report/completeness witness is issued here.
pub(crate) fn actor_tests(source:&ReadSource<'_>,macros:&MacroLines)->Result<Vec<ActorTest>,Failure>{source.checkpoint()?;source.require()?;let mut walker=Walker{source,macros,found:Vec::new(),visited:HashSet::new()};let mut handlers=Vec::new();let mut work=GroupWork{source,peak:0};
 dm_analysis::original_callable_groups::visit_source_values_using(source.inputs(),&mut work,&mut|ordinal,_,_|{let occurrence=source.inputs().archive().occurrences().get(ordinal).ok_or("silicon source value absent")?;let node=source.tree().member(occurrence.member).ok_or("silicon source member absent")?;let owner=source.tree().type_node(node.owner).and_then(|node|source.tree().symbols().text(node.path)).ok_or("silicon source owner absent")?;let name=source.tree().symbols().text(node.name).ok_or("silicon source name absent")?;if is_handler(source,ordinal,owner,name)?{room(source,&mut handlers)?;handlers.push((ordinal,own(source,owner)?,own(source,name)?));}Ok(())})?;
 for(ordinal,owner,name)in handlers{source.checkpoint()?;let params=parameters(source,ordinal)?;let mut taint=Taint::default();for p in &params{if p.path.as_ref().is_some_and(|path|judge::is_act_parts(path.split('/').filter(|p|!p.is_empty()))){charge(source,p.name.len().checked_mul(4).and_then(|n|n.checked_add(1024)))?;taint.acts.insert(own(source,&p.name)?);}}let handler=kc::format(&mut Operation{budget:source.budget(),poll:&||source.checkpoint()},format_args!("{}/proc/{}",if owner=="/"{""}else{&owner},name))?;walker.body(&handler,ordinal,&owner,params,taint,0)?;}
 judge::finalize_using(walker.found,&mut Operation{budget:source.budget(),poll:&||source.checkpoint()})
}
